cat > /tmp/t0.sql <<'EOF'
INSTALL spatial; LOAD spatial;
INSTALL httpfs; LOAD httpfs;
SET geometry_always_xy = true;
.mode line
SELECT count(*) AS n FROM read_parquet('https://data.source.coop/wri-data-lab/trazofields/trazo3-fields/trazo3_brazil_goias_2024.parquet');
EOF
timeout 300 duckdb < /tmp/t0.sql 2>&1 | head -40

cat > /tmp/schema.sql <<'EOF'
LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;
.mode line
SELECT '=== TRAZO3 ===' AS s;
DESCRIBE SELECT * FROM read_parquet('https://data.source.coop/wri-data-lab/trazofields/trazo3-fields/trazo3_brazil_goias_2024.parquet') LIMIT 1;
EOF
timeout 300 duckdb < /tmp/schema.sql 2>&1 | head -100

cat > /tmp/schema2.sql <<'EOF'
