.mode list
SELECT 'TRAZO3' AS f, string_agg(column_name||':'||column_type,' | ') FROM (DESCRIBE SELECT * FROM read_parquet('https://data.source.coop/wri-data-lab/trazofields/trazo3-fields/trazo3_brazil_goias_2024.parquet') LIMIT 1);
SELECT '---CAR---';
SELECT 'CAR' AS f, string_agg(column_name||':'||column_type,' | ') FROM (DESCRIBE SELECT * FROM read_parquet('https://data.source.coop/tristangruppwri/cadastral/brazil-car-area-imovel/brazil_car_area_imovel.parquet') LIMIT 1);
SELECT '---FAC---';
SELECT 'FAC' AS f, string_agg(column_name||':'||column_type,' | ') FROM (DESCRIBE SELECT * FROM read_parquet('https://data.source.coop/tristangruppwri/soft-commodity-infrastructure/facilities/BR_facilities.parquet') LIMIT 1);
EOF
timeout 300 duckdb < /tmp/schema2.sql 2>&1 | head -60

