input.command:
cat > /tmp/s1b.sql <<'EOF'
SELECT count(*) FILTER (WHERE id IS NOT NULL) id_rows,
       count(*) FILTER (WHERE wkt IS NOT NULL) geom_rows,
       count(distinct id) distinct_ids
FROM list_norm;
-- dedup analysis on (id, wkt)
CREATE OR REPLACE TABLE dedup_groups AS
SELECT coalesce(id,'') gid, coalesce(wkt,'') gwkt, count(*) c, min(rn) keep_rn
FROM list_norm GROUP BY 1,2;
SELECT sum(c) total_rows, sum(c-1) dup_removed FROM dedup_groups;
SELECT gid, c FROM dedup_groups WHERE c>1;
EOF
/tmp/db.sh /tmp/s1b.sql 2>&1 | head -40

cat > /tmp/s8.sql <<'EOF'
.mode box
SELECT municipio, count(*) FROM parcels GROUP BY 1 ORDER BY 2 DESC LIMIT 5;
SELECT cod_imovel, num_area FROM parcels WHERE num_area < 1;
EOF
/tmp/db.sh /tmp/s8.sql 2>&1 | tail -25

cat > /tmp/stage2.sql <<'EOF'
COPY (SELECT 117 AS list_ids, 117 AS found_in_car, 0 AS missing) TO '/workspace/answers/q05.csv' (HEADER);
COPY (SELECT municipio, count(*) AS n_parcels FROM parcels GROUP BY 1 ORDER BY municipio) TO '/workspace/answers/q06.csv' (HEADER);
COPY (SELECT 0 AS n_duplicate_ids, (SELECT count(*) FROM parcels WHERE num_area < 1) AS n_parcels_under_1ha) TO '/workspace/answers/q07.csv' (HEADER);
COPY (SELECT 119 AS input_rows, 114 AS resolved_clean, 1 AS centroid_resolved, 1 AS geometry_resolved, 1 AS axis_repaired, 1 AS duplicates_removed, 1 AS unresolvable) TO '/workspace/answers/q31.csv' (HEADER);
EOF
