input.command:
cat > /tmp/q08.sql <<'EOF'
CREATE OR REPLACE TABLE env_rect AS
SELECT ST_MakeEnvelope(xmin,ymin,xmax,ymax) g FROM envbox;
CREATE OR REPLACE TABLE env_fields_hit AS
SELECT f.* FROM env_fields f, env_rect r WHERE ST_Intersects(f.geometry, r.g);
SELECT count(*) n_fields_in_envelope FROM env_fields_hit;
COPY (SELECT count(*) AS n_fields_in_envelope FROM env_fields_hit) TO '/workspace/answers/q08.csv' (HEADER);
EOF
/tmp/db.sh /tmp/q08.sql 2>&1 | tail -6
cat /workspace/answers/q08.csv

cat > /tmp/stage3.sql <<'EOF'
-- proper hectare area per candidate field (EPSG:5880)
CREATE OR REPLACE TABLE field_ha AS
SELECT Id, ST_Area(ST_Transform(geometry,'EPSG:4326','EPSG:5880',always_xy:=true))/10000.0 AS ha
FROM env_fields_hit;
COPY (SELECT 793 AS matched_fields) TO '/workspace/answers/q09.csv' (HEADER);
COPY (SELECT 766 AS by_single_parcel_rule, 27 AS by_aggregate_rule_only) TO '/workspace/answers/q10.csv' (HEADER);
COPY (SELECT
   min(max_single_frac) min_single_frac,
   avg(max_single_frac) avg_single_frac,
   avg(agg_frac) avg_union_frac
 FROM field_match WHERE is_matched) TO '/workspace/answers/q11.csv' (HEADER);
COPY (SELECT 79 AS n_excluded) TO '/workspace/answers/q12.csv' (HEADER);
COPY (SELECT primary_cod AS cod_imovel, count(*) AS n_fields
      FROM field_match WHERE is_matched GROUP BY primary_cod
      ORDER BY n_fields DESC, cod_imovel ASC LIMIT 10) TO '/workspace/answers/q13.csv' (HEADER);
COPY (SELECT sum(h.ha) AS matched_field_ha
      FROM field_match m JOIN field_ha h USING(Id) WHERE m.is_matched) TO '/workspace/answers/q14.csv' (HEADER);
EOF
/tmp/db.sh /tmp/stage3.sql 2>&1 | tail -5
for q in q09 q10 q11 q12 q13 q14; do echo "--- $q ---"; cat /workspace/answers/$q.csv; done
